const webhookData = $('Webhook: Lark Base record created').first().json;
const webhookBody = webhookData.body ?? webhookData;
const token = $json.tenant_access_token;

const rec = webhookBody.record ?? webhookBody.event?.record ?? webhookBody;
const fields = rec.fields ?? webhookBody.fields ?? {};

const record_id = webhookData.query?.record_id
  ?? rec.record_id
  ?? rec.id
  ?? webhookBody.record_id;

return [{ json: { tenant_access_token: token, record_id, fields } }];

const key = $('Load answer key').first().json;
const n   = $('Normalize webhook + carry token').first().json;
const fields = $('Lark: fetch full record').first().json.data?.record?.fields || {};

return key.questions.map(q => ({
  json: {
    record_id: n.record_id,
    tenant_access_token: n.tenant_access_token,
    name:  fields[key.fields.name]  ?? '',
    email: fields[key.fields.email] ?? '',
    passing_score: key.passing_score ?? 17.5,
    rubric_version:  key.version,
    question: q,
    answer:  (fields[q.field_name] ?? '').toString(),
  }
}));

const norm = (s, mode) =>
  mode === 'trim_lower' ? String(s ?? '').trim().toLowerCase() : String(s ?? '').trim();

return $input.all().map(item => {
  const { question, answer } = item.json;
  const match = norm(answer, question.normalize) === norm(question.expected ?? '', question.normalize);
  return {
    json: {
      ...item.json,
      per_question: {
        id: question.id,
        type: 'exact',
        score_field: question.score_field,
        score: match ? question.weight : 0,
        max: question.weight,
        feedback: match ? 'Correct.' : 'Incorrect.'
      }
    }
  };
});

// Recover original question/answer from Build per-question items (HTTP Request node
// discards original fields and replaces them with the Groq API response).
const scenarioItems = $('Build per-question items').all()
  .filter(item => item.json.question.type === 'scenario');

return $input.all().map((groqItem, index) => {
  const llmOutput = groqItem.json;
  const original  = scenarioItems[index]?.json ?? {};
  const question  = original.question ?? {};
  const answer    = original.answer   ?? '';

  let raw = llmOutput.choices?.[0]?.message?.content ?? llmOutput.message?.content ?? '';
  let out;
  try { out = typeof raw === 'string' ? JSON.parse(raw) : raw; }
  catch { out = { score: 0, reasoning: 'Malformed LLM output.', missing_points: [], keywords_found: [] }; }

  const maxQ = question.max_score ?? 5;
  let score = Math.max(0, Math.min(maxQ, Number(out.score) || 0));

  if (question.required_keywords?.length) {
    const lower = (answer || '').toLowerCase();
    const missing = question.required_keywords.filter(k => !lower.includes(k.toLowerCase()));
    if (missing.length) score = Math.min(score, Math.floor(maxQ / 2));
  }

  const weighted = (score * (question.weight ?? 1)) / maxQ;
  return {
    json: {
      ...original,
      per_question: {
        id: question.id ?? `scenario_${index}`,
        type: 'scenario',
        score_field: question.score_field ?? '',
        score: weighted,
        max: question.weight ?? 1,
        raw_score: score,
        max_raw: maxQ,
        feedback: out.reasoning ?? '',
        missing: out.missing_points ?? []
      }
    }
  };
});

const items = $input.all()
  .map(i => i.json.per_question)
  .filter(q => q && q.score_field);
const n     = $('Normalize webhook + carry token').first().json;
const key   = $('Load answer key').first().json;
const fields = $('Lark: fetch full record').first().json.data?.record?.fields || {};

const num = v => Number.isFinite(Number(v)) ? Number(v) : 0;
const score = items.reduce((s, q) => s + num(q.score), 0);
const max   = items.reduce((s, q) => s + num(q.max),   0);
const percent = max > 0 ? Math.round((score / max) * 1000) / 10 : 0;
const pass = score > (key.passing_score ?? 17.5);

// Only PATCH per-question score fields. TOTAL and RESULTS are
// assumed to be Lark formula fields that auto-compute from these.
const patchFields = {};
for (const q of items) {
  patchFields[q.score_field] = num(q.score);
}

return [{
  json: {
    record_id: n.record_id,
    tenant_access_token: n.tenant_access_token,
    name:  fields[key.fields.name]  ?? '',
    email: fields[key.fields.email] ?? '',
    per_question: items,
    score, max, percent,
    result: pass ? 'PASS' : 'FAIL',
    passing_score: key.passing_score ?? 17.5,
    rubric_version: key.version,
    patch_fields: patchFields,
    graded_at: new Date().toISOString()
  }
}];

