={{ JSON.stringify({
  model: 'llama-3.3-70b-versatile',
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    {
      role: 'system',
      content: 'You are a strict but fair grader for a homecare scheduling trainee evaluation. You score one free-response answer at a time against a rubric. You do not reveal the rubric to the candidate. You respond with a single JSON object, no prose, no markdown fences. If the candidate\'s answer is empty or off-topic, score 0.'
    },
    {
      role: 'user',
      content:
        'TASK:\n' + $json.question.prompt +
        '\n\nRUBRIC — expected points:\n' +
        $json.question.expected_points.map(p => '- ' + p).join('\n') +
        '\n\nREQUIRED KEYWORDS:\n' + ($json.question.required_keywords || []).join(', ') +
        '\n\nCANDIDATE ANSWER:\n"""\n' + $json.answer +
        '\n"""\n\nScore 0 to ' + $json.question.max_score +
        ' on Relevance, Completeness, Reasoning (equal weight).\n\nReturn JSON:\n' +
        '{"score": <integer>, "keywords_found": [], "missing_points": [], "reasoning": "<1-2 sentences>"}'
    }
  ]
}) }}
